#!/bin/sh
# vendor/gtk/configure-static.sh -- configure GTK 4.16.7 and its whole stack as STATIC
# libraries, from the source vendored beside it.
#
#     sh vendor/gtk/fetch.sh          # GTK itself
#     sh vendor/gtk/fetch-deps.sh     # the libraries it is built on, pinned
#     sh vendor/gtk/configure-static.sh
#     nice -n 19 ninja -C vendor/gtk/build-static
#
# EVERY OPTION BELOW IS HERE BECAUSE A BUILD FAILED WITHOUT IT. Nine configure rounds on
# 2026-09-19 found eight defects in GTK's own wrap set and two in the compiler's
# relationship with 2024 source; the notes say which is which, so nothing here gets
# deleted later as "probably unnecessary".
set -eu

here=$(cd "$(dirname "$0")" && pwd)
BUILD="$here/build-static"
MESON="$here/.mesonvenv/bin/meson"

[ -x "$MESON" ] || {
    echo "vendor/gtk: no meson at $MESON" >&2
    echo "  /usr/bin/python3 -m venv $here/.mesonvenv && $here/.mesonvenv/bin/pip install meson packaging" >&2
    echo "  (a venv, not dnf: no root needed, and meson 1.12 rather than CRB's 1.4.1)" >&2
    exit 1
}
[ -d "$here/gtk-4.16.7" ]            || { echo "vendor/gtk: run fetch.sh first" >&2; exit 1; }
[ -d "$here/gtk-4.16.7/subprojects/glib" ] || { echo "vendor/gtk: run fetch-deps.sh first" >&2; exit 1; }
[ -f "$here/build-pkgconfig/libdrm.pc" ]   || { echo "vendor/gtk: run fetch-deps.sh first" >&2; exit 1; }

# THE COMPILER WRAPPER, AND WHY THERE HAS TO BE ONE.
#
# pango (33 flags), gdk-pixbuf (14) and glib (8) each call add_project_arguments() with
# a list of '-Werror=<name>'. CC here is clang 24.0.0 from LLVM trunk, which emits
# warnings no released compiler has -- pango 1.54.0, the CURRENT release, dies on
# -Wunused-but-set-global over ordinary G_DEFINE_TYPE boilerplate. A newer library
# version cannot fix that; a trunk compiler will keep inventing warnings.
#
# -Dc_args DOES NOT REACH IT. Meson puts user c_args BEFORE a subproject's project
# arguments, and clang resolves a warning by the LAST flag that names it. Measured here
# on 2026-09-19, compiling one file that sets an unused static:
#
#     -Werror=unused-but-set-variable                                    FAILS
#     -Werror=unused-but-set-variable  -Wno-error=unused-but-set-variable   OK   (after)
#     -Wno-error=unused-but-set-variable  -Werror=unused-but-set-variable FAILS  (before)
#     -Wno-unused-but-set-global  -Werror=unused-but-set-variable         FAILS  (before)
#
# Note the second line especially: plain -Wno-error does NOT cancel a specific
# -Werror=<name>, only a blanket -Werror. Every flag we can pass lands in the losing
# slot, so the only place left is after the compiler's own argument list -- a wrapper.
#
# IT APPENDS -w: no warnings at all, for THIS BUILD ONLY. That is defensible precisely
# here and nowhere else -- GTK and its stack are other people's finished source, vendored
# unmodified, and their warnings are not ours to act on. Real errors are untouched
# (checked: a call to an undeclared function still fails with -w). satellite's own code
# is built by its own Makefile and keeps every warning it has.
CCDIR="$here/build-cc"
REAL_CC=$(command -v "${CC:-cc}")
REAL_CXX=$(command -v "${CXX:-c++}")
mkdir -p "$CCDIR"
for pair in "cc:$REAL_CC" "c++:$REAL_CXX"; do
    name=${pair%%:*}
    real=${pair#*:}
    cat > "$CCDIR/$name" <<EOF
#!/bin/sh
# GENERATED by vendor/gtk/configure-static.sh. Appends -w AFTER the caller's arguments,
# which is the only position that defeats a subproject's own -Werror=<name>.
exec "$real" "\$@" -w
EOF
    chmod +x "$CCDIR/$name"
done
CC="$CCDIR/cc"
CXX="$CCDIR/c++"
export CC CXX
echo "vendor/gtk: building with $REAL_CC through a -w wrapper"

rm -rf "$BUILD"

PATH="$here/.mesonvenv/bin:$PATH"
export PATH
PKG_CONFIG_PATH="$here/build-pkgconfig"
export PKG_CONFIG_PATH

"$MESON" setup "$BUILD" "$here/gtk-4.16.7" \
  --default-library=static \
  --wrap-mode=forcefallback \
  --prefix="$here/stage-static" \
  \
  `# HB_NO_PRAGMA_GCC_DIAGNOSTIC_ERROR: harfbuzz promotes ~30 warnings to errors with` \
  `# '#pragma GCC diagnostic error' inside hb.hh, which no command-line flag can reach.` \
  `# macro is harfbuzz's own escape hatch (src/hb.hh:64) and is what distributions set.` \
  -Dcpp_args=-DHB_NO_PRAGMA_GCC_DIAGNOSTIC_ERROR \
  \
  `# Nothing that is not the library itself.` \
  -Dintrospection=disabled -Ddocumentation=false -Dman-pages=false \
  -Dbuild-demos=false -Dbuild-testsuite=false -Dbuild-examples=false -Dbuild-tests=false \
  -Dmedia-gstreamer=disabled -Dprint-cups=disabled \
  \
  `# Vulkan off: it needs glslc and a Vulkan loader, and GSK's GL renderer is enough to` \
  `# prove a window. Worth revisiting once the window works -- satl-term links libvulkan` \
  `# today, so satl and satl-term would then differ in how they draw.` \
  -Dvulkan=disabled \
  \
  `# WAYLAND ONLY. The X11 backend needs libX11, libXext, libXi, libXcursor, libXdamage,` \
  `# libXfixes, libXinerama and libXrandr, and NONE of them has a wrap -- every one would` \
  `# link as a system .so and quietly un-static the binary. This machine is Wayland. An` \
  `# X11 satl is a separate decision with its own vendoring, not a flag.` \
  -Dx11-backend=false -Dwayland-backend=true \
  \
  `# freetype <-> harfbuzz is a cycle: cairo asks fontconfig, fontconfig asks freetype,` \
  `# freetype asks harfbuzz (for auto-hinting), harfbuzz asks freetype. Meson refuses` \
  `# with "Recursive include of subprojects". freetype's own option breaks it; the cost` \
  `# is hinting quality for glyphs a font's cmap does not address directly. Cosmetic.` \
  -Dfreetype2:harfbuzz=disabled \
  \
  `# libmount and libselinux ARE FOUND ON THIS SYSTEM AS .so AND HAVE NO WRAP. Left at` \
  `# their defaults, glib links them and the binary comes out "static" with two dynamic` \
  `# dependencies inside it and no warning anywhere. This is the one a reading of the` \
  `# build would have missed.` \
  -Dglib:selinux=disabled -Dglib:libmount=disabled \
  -Dglib:tests=false -Dglib:introspection=disabled -Dglib:nls=disabled \
  \
  `# builtin_loaders=all IS THE WHOLE POINT OF PINNING gdk-pixbuf. Its image loaders are` \
  `# normally dlopen()ed modules found through a loaders.cache, and a static binary on a` \
  `# machine with no gdk-pixbuf installed has neither the modules nor the cache. "all"` \
  `# compiles them into the library instead. (It is why libjpeg-turbo and libtiff join` \
  `# the build.)` \
  -Dgdk-pixbuf:builtin_loaders=all \
  -Dgdk-pixbuf:tests=false -Dgdk-pixbuf:introspection=disabled -Dgdk-pixbuf:man=false \
  \
  -Dpango:introspection=disabled \
  -Dgraphene:introspection=disabled -Dgraphene:tests=false \
  \
  `# libxkbcommon, now that fetch-deps.sh wraps it (GTK ships no wrap; this was the last` \
  `# undefined symbol in the static link). No X11, no docs, no command-line tools, and no` \
  `# xkbregistry -- the registry parses rules XML and would drag libxml2 in for a feature` \
  `# satellite does not use. enable-wayland stays on: that is our backend.` \
  `#` \
  `# xkb-config-root is the path COMPILED IN as the default place to look for` \
  `# xkeyboard-config data. It is set to a path that will not exist on a target machine` \
  `# ON PURPOSE: satl must spill its own embedded copy and point XKB_CONFIG_ROOT at it` \
  `# before gtk_init, and a build that silently found the developer machine's` \
  `# /usr/share/X11/xkb would hide that requirement until someone else ran the binary.` \
  -Dxkbcommon:enable-x11=false -Dxkbcommon:enable-docs=false \
  -Dxkbcommon:enable-tools=false -Dxkbcommon:enable-xkbregistry=false \
  -Dxkbcommon:enable-bash-completion=false \
  -Dxkbcommon:xkb-config-root=/nonexistent/satl-must-provide-xkb-data \
  \
  `# fontconfig asks for intl too (meson.build:236) with a declared fallback. With nls` \
  `# off it stops being required, so removing the proxy-libintl wrap does not break it.` \
  -Dfontconfig:nls=disabled \
  \
  `# ---- PURITY: each of these removes a system .so the binary was acquiring by accident.` \
  `# Found by auditing the configure log for "Run-time dependency ... found: YES", which` \
  `# is meson saying "from the system"; and then confirmed by the link failing on the` \
  `# exact symbols. -Dx11-backend=false on GTK does NOT stop cairo and pango turning on` \
  `# their OWN X backends: x11, xcb, xcb-render, xcb-shm, xext, xrender and xft all` \
  `# resolved from /usr/lib64 with no warning at any stage.` \
  -Dcairo:xlib=disabled -Dcairo:xcb=disabled \
  -Dpango:xft=disabled \
  \
  `# libthai: pango break-thai.c calls th_brk_new/th_uni2tis. Undefined at link time.` \
  `# Losing it costs Thai word-breaking, which needs a Thai dictionary on the target` \
  `# anyway and so could never have worked in a self-contained binary.` \
  -Dpango:libthai=disabled \
  \
  `# freetype: brotli is WOFF2 web fonts (BrotliDecoderDecompress), bzip2 is` \
  `# bzip2-compressed PCF fonts (BZ2_bzDecompressInit). Both undefined at link time,` \
  `# both for font formats satellite will never open.` \
  -Dfreetype2:brotli=disabled -Dfreetype2:bzip2=disabled \
  \
  `# gio_sniffing=false IS WHAT MAKES builtin_loaders=all ACTUALLY WORK. Left at its` \
  `# default of true, gdk-pixbuf picks a loader ONLY via g_content_type_guess() -- the` \
  `# system MIME database, found through XDG_DATA_DIRS -- so on a machine with no` \
  `# shared-mime-info the loaders compiled INTO the binary are unreachable and every` \
  `# image fails with "Couldn't recognize the image file format". false switches to` \
  `# matching magic signatures, which needs nothing outside the process. Note that` \
  `# shared-mime-info has no wrap, so forcefallback resolves it from the system and the` \
  `# build succeeds in silence -- nothing warns you that the flag you set did nothing.` \
  -Dgdk-pixbuf:gio_sniffing=false \
  \
  `# libepoxy: NO GLX, NO X11, NO TESTS. Its glx_static test links -static against` \
  `# /usr/lib64/libX11.so and ld.lld refuses outright --` \
  `#     ld.lld: error: attempted static link of dynamic object /usr/lib64/libX11.so` \
  `# -- which is the clearest possible statement of the problem: X11 has no wrap, so it` \
  `# can only ever arrive as a system .so. Turning glx and x11 off removes libX11 from` \
  `# the graph entirely rather than only skipping the test that noticed. EGL is left at` \
  `# auto: that is the Wayland path, and epoxy dlopen()s libEGL at RUN time by design.` \
  -Dlibepoxy:tests=false -Dlibepoxy:glx=no -Dlibepoxy:x11=false \
  \
  `# harfbuzz tests default to ENABLED and build fuzzers we will never run.` \
  -Dharfbuzz:tests=disabled -Dharfbuzz:docs=disabled \
  -Dharfbuzz:icu=disabled -Dharfbuzz:cairo=disabled -Dharfbuzz:chafa=disabled \
  \
  `# wayland-protocols' test subdir wants a wayland-scanner dependency that the wayland` \
  `# subproject does not override, so the tests cannot configure at all.` \
  -Dwayland-protocols:tests=false \
  -Dwayland:tests=false -Dwayland:documentation=false -Dwayland:dtd_validation=false

echo
echo "vendor/gtk: configured. Next:"
echo "    nice -n 19 ninja -C $BUILD -j 16"
echo "  (niced on purpose -- an un-niced parallel build of this size makes the desktop"
echo "   stutter, the same argument satl-term/child.cpp makes about the interpreter.)"
